//! The quote widget's built-in sayings: real quotations, each checked
//! against a source before it went in (Wikiquote's sourced sections or the
//! work itself, never the "attributed" or "misattributed" kind). The source
//! of every line, with the link it was checked against, is in `SAYINGS.md`
//! next to this file; add a saying there when you add one here.

use mandara_i18n::tk;

/// A built-in saying. Every field is a catalog key, translated at display
/// time; `work` is empty for proverbs, which have no single source.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Saying {
    pub text: &'static str,
    pub author: &'static str,
    pub work: &'static str,
}

